func bagMergeReturnType(context CustomReturnTypeContext) Symbol {
	indexes := argumentIndexesForParameter(context, "bag")
	if len(indexes) == 0 && context.Signature == nil && len(context.ArgumentParameters) == 0 {
		indexes = make([]int, 0, len(context.ArgumentResultSymbols))
		for i := range context.ArgumentResultSymbols {
			indexes = append(indexes, i)
		}
	}
	if len(indexes) == 0 {
		return ScalarTypes.DynamicBag
	}
	merged := dynamicBagArgumentAt(context, indexes[0])
	if merged == nil {
		return ScalarTypes.DynamicBag
	}
	for _, index := range indexes[1:] {
		if bag := dynamicBagArgumentAt(context, index); bag != nil {
			merged = ScalarTypes.GetDynamicBag(UnionColumns(merged.Properties(), bag.Properties())...)
		}
	}
	return merged
}

func bagRemoveKeysReturnType(context CustomReturnTypeContext) Symbol {
	bagIndex := firstArgumentIndexForParameter(context, "bag")
	keysIndex := firstArgumentIndexForParameter(context, "keys")
	bag := dynamicBagArgumentAt(context, bagIndex)
	keys, ok := constantStringSliceArgument(context, keysIndex)
	if bag == nil || !ok {
		return ScalarTypes.DynamicBag
	}
	remove := map[string]bool{}
	for _, key := range keys {
		remove[key] = true
	}
	properties := []*ColumnSymbol{}
	for _, property := range bag.Properties() {
		if property != nil && !remove[property.SymbolName()] {
			properties = append(properties, property)
		}
	}
	return ScalarTypes.GetDynamicBag(properties...)
}

func bagSetKeyReturnType(context CustomReturnTypeContext) Symbol {
	bagIndex := firstArgumentIndexForParameter(context, "bag")
	keyIndex := firstArgumentIndexForParameter(context, "key")
	valueIndex := firstArgumentIndexForParameter(context, "value")
	name, ok := constantStringArgument(context, keyIndex)
	if !ok {
		return bagSetKeyFallbackReturn(context, bagIndex)
	}
	name = strings.TrimSpace(name)
	if name == "" {
		return bagSetKeyFallbackReturn(context, bagIndex)
	}

	valueType := argumentTypeAt(context, valueIndex)
	if valueType == nil {
		return bagSetKeyFallbackReturn(context, bagIndex)
	}
	currentBag := dynamicBagArgumentAt(context, bagIndex)
	if currentBag == nil {
		currentBag = ScalarTypes.DynamicBag
	}

	if strings.HasPrefix(name, "$") {
		path, ok := bagSetKeyJSONPathSegments(name)
		if !ok {
			return bagSetKeyFallbackReturn(context, bagIndex)
		}
		return addOrUpdateDynamicBagJSONPath(currentBag, path, valueType)
	}
	if isJSONPathKey(name) {
		return bagSetKeyFallbackReturn(context, bagIndex)
	}
	return currentBag.AddOrUpdateProperty(NewColumnSymbol(name, valueType))
}

func bagSetKeyFallbackReturn(context CustomReturnTypeContext, bagIndex int) Symbol {
	if symbol := argumentResultSymbolAt(context, bagIndex); symbol != nil {
		return symbol
	}
	if typ := argumentTypeAt(context, bagIndex); typ != nil && typ != ScalarTypes.Unknown.Type() {
		return typ
	}
	return ScalarTypes.DynamicBag
}

func isJSONPathKey(key string) bool {
	return strings.ContainsAny(key, "$.[]")
}

func bagSetKeyJSONPathSegments(key string) ([]string, bool) {
	key = strings.TrimSpace(key)
	if !strings.HasPrefix(key, "$") || key == "$" {
		return nil, false
	}
	rest := key[1:]
	if rest == "" || strings.Contains(rest, "$") {
		return nil, false
	}
	segments := []string{}
	for rest != "" {
		switch {
		case strings.HasPrefix(rest, "."):
			rest = rest[1:]
			if rest == "" {
				return nil, false
			}
			name, tail := readJSONPathIdentifier(rest)
			if name == "" {
				return nil, false
			}
			segments = append(segments, name)
			rest = tail
		case strings.HasPrefix(rest, "["):
			name, tail, ok := readJSONPathQuotedProperty(rest)
			if !ok || name == "" {
				return nil, false
			}
			segments = append(segments, name)
			rest = tail
		default:
			return nil, false
		}
	}
	return segments, len(segments) > 0
}

func readJSONPathIdentifier(text string) (string, string) {
	text = strings.TrimSpace(text)
	if text == "" {
		return "", ""
	}
	runes := []rune(text)
	if len(runes) == 0 || !(unicode.IsLetter(runes[0]) || runes[0] == '_' || runes[0] == '$') {
		return "", text
	}
	end := 1
	for end < len(runes) && (unicode.IsLetter(runes[end]) || unicode.IsDigit(runes[end]) || runes[end] == '_' || runes[end] == '$') {
		end++
	}
	return string(runes[:end]), string(runes[end:])
}

func readJSONPathQuotedProperty(text string) (string, string, bool) {
	if !strings.HasPrefix(text, "[") || len(text) < 4 {
		return "", text, false
	}
	quote := text[1]
	if quote != '\'' && quote != '"' {
		return "", text, false
	}
	escaped := false
	for i := 2; i < len(text); i++ {
		ch := text[i]
		if escaped {
			escaped = false
			continue
		}
		if ch == '\\' {
			escaped = true
			continue
		}
		if ch != quote {
			continue
		}
		if i+1 >= len(text) || text[i+1] != ']' {
			return "", text, false
		}
		value := text[2:i]
		if quote == '"' {
			if unquoted, err := strconv.Unquote(text[1 : i+1]); err == nil {
				value = unquoted
			}
		} else {
			value = strings.ReplaceAll(value, `\'`, `'`)
			value = strings.ReplaceAll(value, `\\`, `\`)
		}
		return value, text[i+2:], true
	}
	return "", text, false
}

func addOrUpdateDynamicBagJSONPath(bag *DynamicBagSymbol, path []string, valueType *TypeSymbol) *DynamicBagSymbol {
	if len(path) == 0 {
		if bag == nil {
			return ScalarTypes.DynamicBag
		}
		return bag
	}
	if bag == nil {
		bag = ScalarTypes.DynamicBag
	}
	name := strings.TrimSpace(path[0])
	if name == "" {
		return bag
	}
	if existing, ok := dynamicBagPropertyByFoldedName(bag, name); ok {
		name = existing.SymbolName()
	}
	if len(path) == 1 {
		return bag.AddOrUpdateProperty(NewColumnSymbol(name, valueType))
	}
	var nestedBag *DynamicBagSymbol
	if existing, ok := dynamicBagPropertyByFoldedName(bag, name); ok {
		nestedBag, _ = DynamicBagForType(existing.Type)
	}
	updated := addOrUpdateDynamicBagJSONPath(nestedBag, path[1:], valueType)
	return bag.AddOrUpdateProperty(NewColumnSymbol(name, updated.Type()))
}

func dynamicBagPropertyByFoldedName(bag *DynamicBagSymbol, name string) (*ColumnSymbol, bool) {
	if bag == nil || name == "" {
		return nil, false
	}
	for _, property := range bag.Properties() {
		if property != nil && property.SymbolName() == name {
			return property, true
		}
	}
	for _, property := range bag.Properties() {
		if property != nil && strings.EqualFold(property.SymbolName(), name) {
			return property, true
		}
	}
	return nil, false
}

func firstArgumentIndexForParameter(context CustomReturnTypeContext, parameterName string) int {
	indexes := argumentIndexesForParameter(context, parameterName)
	if len(indexes) > 0 {
		return indexes[0]
	}
	return -1
}

func argumentIndexesForParameter(context CustomReturnTypeContext, parameterName string) []int {
	parameter := (*Parameter)(nil)
	if context.Signature != nil {
		parameter = context.Signature.GetParameter(parameterName)
	}
	indexes := []int{}
	for i, candidate := range context.ArgumentParameters {
		if parameter != nil {
			if candidate == parameter {
				indexes = append(indexes, i)
			}
			continue
		}
		if candidate != nil && candidate.Name == parameterName {
			indexes = append(indexes, i)
		}
	}
	return indexes
}

func argumentTypesForParameter(context CustomReturnTypeContext, parameterName string) []*TypeSymbol {
	indexes := argumentIndexesForParameter(context, parameterName)
	if len(indexes) == 0 && context.Signature == nil && len(context.ArgumentParameters) == 0 {
		return append([]*TypeSymbol{}, context.ArgumentTypes...)
	}
	types := make([]*TypeSymbol, 0, len(indexes))
	for _, index := range indexes {
		types = append(types, argumentTypeAt(context, index))
	}
	return types
}

func argumentTypeAt(context CustomReturnTypeContext, index int) *TypeSymbol {
	if symbol := argumentResultSymbolAt(context, index); symbol != nil {
		if typ := returnTypeFromSymbol(symbol); typ != nil {
			return typ
		}
	}
	if index >= 0 && index < len(context.ArgumentTypes) && context.ArgumentTypes[index] != nil {
		return context.ArgumentTypes[index]
	}
	if index >= 0 && index < len(context.ArgumentSemantics) && context.ArgumentSemantics[index].ResultType != nil {
		return context.ArgumentSemantics[index].ResultType
	}
	return ScalarTypes.Unknown.Type()
}

func argumentResultSymbolAt(context CustomReturnTypeContext, index int) Symbol {
	if index >= 0 && index < len(context.ArgumentResultSymbols) && context.ArgumentResultSymbols[index] != nil {
		return context.ArgumentResultSymbols[index]
	}
	return nil
}

func dynamicBagArgumentAt(context CustomReturnTypeContext, index int) *DynamicBagSymbol {
	if bag, ok := argumentResultSymbolAt(context, index).(*DynamicBagSymbol); ok {
		return bag
	}
	if typ := argumentTypeAt(context, index); sameType(typ, ScalarTypes.DynamicBag.Type()) {
		return ScalarTypes.DynamicBag
	}
	return nil
}

func constantStringArgument(context CustomReturnTypeContext, index int) (string, bool) {
	if index >= 0 && index < len(context.ArgumentConstantValues) {
		if value, ok := context.ArgumentConstantValues[index].(string); ok {
			return value, true
		}
	}
	return "", false
}

func constantStringSliceArgument(context CustomReturnTypeContext, index int) ([]string, bool) {
	if index < 0 || index >= len(context.ArgumentConstantValues) {
		return nil, false
	}
	switch value := context.ArgumentConstantValues[index].(type) {
	case []string:
		return append([]string{}, value...), true
	case []any:
		out := make([]string, 0, len(value))
		for _, item := range value {
			text, ok := item.(string)
			if !ok {
				return nil, false
			}
			out = append(out, text)
		}
		return out, true
	default:
		return nil, false
	}
}

func noneResultSymbolFunction(name string, returnSymbol Symbol, parameters ...*Parameter) *FunctionSymbol {
	return NewFunctionSymbol(name, NewSymbolSignature(returnSymbol, parameters...)).
		ConstantFoldable().
		WithResultNameKind(ResultNameNone)
}

func dateTimePartFunction(name string, returnType *TypeSymbol, parts []string, parameters ...*Parameter) *FunctionSymbol {
	values := parameterStringValues(parts)
	allParameters := make([]*Parameter, 0, len(parameters)+1)
	allParameters = append(allParameters, p("part", ScalarTypes.String, WithArgumentKind(ArgumentKindLiteral), WithParameterValues(values...)))
	allParameters = append(allParameters, parameters...)
	return noneResultFunction(name, returnType, allParameters...)
}

func convertFunction(name string, units []string) *FunctionSymbol {
	values := parameterStringValues(units)
	return NewScalarFunctionSymbol(name, ScalarTypes.Real.Type(),
		p("value", ScalarTypes.Real),
		p("from", ScalarTypes.String, WithArgumentKind(ArgumentKindExpression), WithParameterValues(values...)),
		p("to", ScalarTypes.String, WithArgumentKind(ArgumentKindExpression), WithParameterValues(values...)),
	).ConstantFoldable().WithResultNameKind(ResultNameNone)
}

func parameterStringValues(values []string) []any {
	out := make([]any, 0, len(values))
	for _, value := range values {
		out = append(out, value)
	}
	return out
}

